-- ----------------------------
-- Table structure for material_issuing
-- ----------------------------
DROP TABLE IF EXISTS "public"."material_issuing";
CREATE TABLE "public"."material_issuing" (
  "id" int4 NOT NULL DEFAULT nextval('material_issuing_id_seq'::regclass),
  "issuing_no" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "issuing_date" timestamp(6) NOT NULL,
  "material_id" int4,
  "total_quantity" numeric(15,2) NOT NULL,
  "unit" varchar(50) COLLATE "pg_catalog"."default",
  "department" varchar(100) COLLATE "pg_catalog"."default",
  "work_order_no" varchar(50) COLLATE "pg_catalog"."default",
  "remark" text COLLATE "pg_catalog"."default",
  "status" varchar(20) COLLATE "pg_catalog"."default" DEFAULT 'COMPLETED'::character varying,
  "create_date" timestamp(6) DEFAULT now(),
  "create_by" varchar(255) COLLATE "pg_catalog"."default",
  "update_date" timestamp(6) DEFAULT now(),
  "update_by" varchar(255) COLLATE "pg_catalog"."default",
  "issuing_type" varchar(50) COLLATE "pg_catalog"."default" DEFAULT 'NORMAL_PRODUCTION'::character varying,
  "machine_no" varchar(50) COLLATE "pg_catalog"."default",
  "part_no" varchar(50) COLLATE "pg_catalog"."default",
  "requester" varchar(100) COLLATE "pg_catalog"."default",
  "production_order_id" int4,
  "required_quantity" numeric(15,4)
)
;
COMMENT ON COLUMN "public"."material_issuing"."issuing_type" IS 'Type of issuing: NORMAL_PRODUCTION, STOCK_DEDUCTION, SPARE_PARTS_REPLACEMENT';
COMMENT ON COLUMN "public"."material_issuing"."production_order_id" IS 'เชื่อมโยงกับคำสั่งผลิต';
COMMENT ON COLUMN "public"."material_issuing"."required_quantity" IS 'จำนวนที่ต้องใช้ตาม BOM';

